def pick(d, keys):
    for k in keys:
        try:
            v = d[k]
            if v:
                return v
        except Exception:
            pass
    return None

def handles_from(r):
    hs = pick(r.output, ["evidence_handles"])
    if hs:
        return list(hs)
    h = pick(r.output, ["evidence_handle"])
    if h:
        return [h]
    return []

